#include <vector>
#include <algorithm>

class Solution {
public:
    int minDifference(std::vector<int>& nums) {
        if (nums.size() <= 4) return 0;
        std::sort(nums.begin(), nums.end());
        int n = nums.size();
        return std::min({
            nums[n - 1] - nums[3],
            nums[n - 2] - nums[2],
            nums[n - 3] - nums[1],
            nums[n - 4] - nums[0]
        });
    }
};

import java.util.*;

class Solution {
    public int minDifference(int[] nums) {
        if (nums.length <= 4) return 0;
        Arrays.sort(nums);
        int n = nums.length;
        int ans = nums[n - 1] - nums[3];
        ans = Math.min(ans, nums[n - 2] - nums[2]);
        ans = Math.min(ans, nums[n - 3] - nums[1]);
        ans = Math.min(ans, nums[n - 4] - nums[0]);
        return ans;
    }
}

var minDifference = function(nums) {
    if (nums.length <= 4) return 0;
    nums.sort((a, b) => a - b);
    const n = nums.length;
    return Math.min(
        nums[n - 1] - nums[3],
        nums[n - 2] - nums[2],
        nums[n - 3] - nums[1],
        nums[n - 4] - nums[0]
    );
};
